-- Function: public.fn_get_intelligence_operational_overview
-- Backup generated on 2026-10-25 20:33:25

CREATE OR REPLACE FUNCTION public.fn_get_intelligence_operational_overview(p_tenant_id uuid, p_org_id uuid, p_branch_id uuid, p_classroom_id uuid, p_start_date timestamp with time zone, p_end_date timestamp with time zone)  RETURNS TABLE(total_attendance integer, present_count integer, absent_count integer, late_count integer, total_classrooms integer, planned_classrooms integer, planned_experiences integer, completed_experiences integer, upcoming_experiences integer, moments_count integer, care_count integer)  LANGUAGE sql  STABLE AS $function$     WITH att AS (         SELECT              COUNT(*)::int AS total_att,             COUNT(*) FILTER (WHERE ca.status = 'Present')::int AS present_cnt,             COUNT(*) FILTER (WHERE ca.status = 'Absent')::int AS absent_cnt,             COUNT(*) FILTER (WHERE ca.status = 'Late')::int AS late_cnt         FROM child_attendance ca         JOIN classrooms cl ON ca.classroom_id = cl.id         JOIN branches b ON cl.branch_id = b.id         WHERE ca.tenant_id = p_tenant_id           AND b.organization_id = p_org_id           AND (p_branch_id IS NULL OR b.id = p_branch_id)           AND (p_classroom_id IS NULL OR cl.id = p_classroom_id)           AND ca.attendance_date BETWEEN p_start_date::date AND p_end_date::date     ),     cls AS (         SELECT              COUNT(DISTINCT cl.id)::int AS total_cls,             COUNT(DISTINCT es.classroom_id)::int AS planned_cls         FROM classrooms cl         JOIN branches b ON cl.branch_id = b.id         LEFT JOIN experience_schedules es ON cl.id = es.classroom_id               AND es.tenant_id = p_tenant_id              AND es.scheduled_date BETWEEN p_start_date::date AND p_end_date::date         WHERE cl.tenant_id = p_tenant_id           AND b.organization_id = p_org_id           AND (p_branch_id IS NULL OR b.id = p_branch_id)           AND (p_classroom_id IS NULL OR cl.id = p_classroom_id)           AND cl.is_active = true     ),     exp AS (         SELECT              COUNT(*)::int AS planned_exp,             COUNT(*) FILTER (WHERE es.status IN ('Completed', 'Finished'))::int AS completed_exp,             COUNT(*) FILTER (WHERE es.status IN ('Confirmed', 'Scheduled'))::int AS upcoming_exp         FROM experience_schedules es         JOIN classrooms cl ON es.classroom_id = cl.id         JOIN branches b ON cl.branch_id = b.id         WHERE es.tenant_id = p_tenant_id           AND b.organization_id = p_org_id           AND (p_branch_id IS NULL OR b.id = p_branch_id)           AND (p_classroom_id IS NULL OR cl.id = p_classroom_id)           AND es.scheduled_date BETWEEN p_start_date::date AND p_end_date::date     ),     act AS (         SELECT              (SELECT COUNT(*)::int               FROM child_journey_entries cje              JOIN classrooms cl ON cje.classroom_id = cl.id              JOIN branches b ON cl.branch_id = b.id              WHERE cje.tenant_id = p_tenant_id                AND b.organization_id = p_org_id                AND (p_branch_id IS NULL OR b.id = p_branch_id)                AND (p_classroom_id IS NULL OR cl.id = p_classroom_id)                AND cje.observation_date >= p_start_date::date                 AND cje.observation_date <= p_end_date::date) AS moments_cnt,             (SELECT COUNT(*)::int              FROM child_care_events cce              JOIN classrooms cl ON cce.classroom_id = cl.id              JOIN branches b ON cl.branch_id = b.id              WHERE cce.tenant_id = p_tenant_id                AND b.organization_id = p_org_id                AND (p_branch_id IS NULL OR b.id = p_branch_id)                AND (p_classroom_id IS NULL OR cl.id = p_classroom_id)                AND cce.event_time >= p_start_date                 AND cce.event_time <= p_end_date) AS care_cnt     )     SELECT          att.total_att, att.present_cnt, att.absent_cnt, att.late_cnt,         cls.total_cls, cls.planned_cls,         exp.planned_exp, exp.completed_exp, exp.upcoming_exp,         act.moments_cnt, act.care_cnt     FROM att, cls, exp, act; $function$ ;
